private double CalculateHighVisitDiscount(DiscountManager ctx)
{
    // Example: early-return style and small helpers
    if (ctx.CustomerType != 2) return 20.0;
    if (ctx.MembershipLevel != "Diamond") return 25.0;
    if (ctx.MonthsSinceMembership <= 24) return 30.0;
    if (ctx.AverageSpend <= 75) return 35.0;
    if (ctx.ConsecutiveVisits <= 10) return 40.0;
    if (ctx.LeftReview && ctx.ReviewStars == 5)
        return ctx.ReferralCount > 10 ? 60.0 : 45.0;
    return 45.0;
}

